set search_path = scheduler, public;
begin;
update projects set quote_stage='SUBMITTED', quote_type='FULL QUOTE', scope='Joinery', raised_by='SOFIA', quote_submitted_date=coalesce(quote_submitted_date,null), estimator_id=coalesce(estimator_id,(select id from people where name='RAMUS')) where enquiry_no='26-095';
update projects set quote_stage='SUBMITTED', quote_type='FULL QUOTE', scope='Joinery', raised_by=null, quote_submitted_date=coalesce(quote_submitted_date,null), estimator_id=coalesce(estimator_id,(select id from people where name='RAMUS')) where enquiry_no='2324';
update projects set quote_stage='SUBMITTED', quote_type='KITCHEN', scope='Joinery', raised_by='CLIENT', quote_submitted_date=coalesce(quote_submitted_date,null), estimator_id=coalesce(estimator_id,(select id from people where name='RAMUS')) where enquiry_no='26-009';
commit;
